// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type DownwardTrendChartProps = Record<string, any>;

const DownwardTrendChart: React.FC<DownwardTrendChartProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 4,
  barColor = "#ef4444", // Red as requested
  textColor = "#ffffff",
  highlightText = "49%",
  descriptionText = "LESS THAN 2026",
  baselineColor = "rgba(255, 255, 255, 0.2)",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Hardcoded data points representing a downward trend
  const dataPoints = [0.95, 0.85, 0.70, 0.55, 0.38, 0.25];
  const numBars = dataPoints.length;

  // Responsive Layout Calculations optimized for 9:16
  const safeAreaSide = width * 0.1;
  const chartWidth = width - safeAreaSide * 2;
  const chartHeight = height * 0.35;
  const chartTop = height * 0.5;

  const barGap = chartWidth * 0.04;
  const totalGapWidth = barGap * (numBars - 1);
  const barWidth = (chartWidth - totalGapWidth) / numBars;

  // Text Animation Logic
  const textEntranceStart = 20;
  const textProgress = spring({
    fps,
    frame: frame - textEntranceStart,
    config: { damping: 14, mass: 1.2 },
  });
  
  const textOpacity = interpolate(frame - textEntranceStart, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const textYOffset = interpolate(textProgress, [0, 1], [50, 0]);
  const textScale = interpolate(textProgress, [0, 1], [0.9, 1]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      
      {/* Text Section (Top Safe Zone) */}
      <div
        style={{
          position: "absolute",
          top: height * 0.15,
          left: 0,
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          opacity: textOpacity,
          transform: `translateY(${textYOffset}px) scale(${textScale})`,
          transition: "none",
        }}
      >
        <div style={{
          fontSize: height * 0.12,
          fontWeight: 900,
          color: barColor,
          lineHeight: 1,
          letterSpacing: "-2px",
          textShadow: `0px 10px 30px ${barColor}40`,
        }}>
          {highlightText}
        </div>
        <div style={{
          fontSize: height * 0.04,
          fontWeight: 600,
          color: textColor,
          marginTop: height * 0.02,
          letterSpacing: "2px",
          textAlign: "center",
          width: "80%",
        }}>
          {descriptionText}
        </div>
      </div>

      {/* Chart Section (Middle/Bottom) */}
      <div
        style={{
          position: "absolute",
          left: safeAreaSide,
          top: chartTop,
          width: chartWidth,
          height: chartHeight,
        }}
      >
        {/* Baseline */}
        <div
          style={{
            position: "absolute",
            bottom: 0,
            left: 0,
            width: "100%",
            height: 4,
            backgroundColor: baselineColor,
            borderRadius: 2,
            opacity: interpolate(frame, [0, 10], [0, 1], { extrapolateRight: "clamp" }),
          }}
        />

        {/* Bars */}
        {dataPoints.map((value, index) => {
          // Stagger the animation of each bar
          const delay = index * 6;
          const barProgress = spring({
            fps,
            frame: frame - delay,
            config: { damping: 12, stiffness: 100 },
          });

          // Calculate visual properties
          const targetHeight = value * chartHeight;
          const currentHeight = interpolate(barProgress, [0, 1], [0, targetHeight]);
          const xPosition = index * (barWidth + barGap);
          
          // Subtle color variation: older bars (left) are slightly darker, newest (right) is brightest red
          const opacityVal = interpolate(index, [0, numBars - 1], [0.6, 1]);

          return (
            <div
              key={index}
              style={{
                position: "absolute",
                bottom: 4, // Rest right above the baseline
                left: xPosition,
                width: barWidth,
                height: currentHeight,
                backgroundColor: barColor,
                opacity: opacityVal,
                borderRadius: "12px 12px 4px 4px",
                transition: "none",
                // Subtle gradient for depth
                backgroundImage: `linear-gradient(to bottom, ${barColor}, ${barColor}80)`,
                boxShadow: `0 0 20px ${barColor}30`,
              }}
            />
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default DownwardTrendChart;